SELECT jsonb_build_object('rows',(SELECT jsonb_agg(jsonb_build_object('id',id_historico,'event',id_evento,'entity',entidade,'operation',operacao,'changes',alteracoes) ORDER BY id_historico) FROM tb_evento_fatos_historico WHERE id_evento IN (43657,39395,37774,38982) AND registrado_em>=date '2026-10-30'),'routes',(SELECT jsonb_agg(jsonb_build_object('id',id_evento_percurso,'event',id_evento,'km',percurso_evento,'date',data_percurso,'start',hora_largada,'locked',percurso_bloqueado) ORDER BY id_evento,percurso_evento) FROM tb_evento_corridas_percursos WHERE id_evento IN (43657,39395)))::text payload
